"""Build a separate voice adaptation, preserving the original chat checklist byte-for-byte."""
from copy import deepcopy
from pathlib import Path

from server import atomic_json, read_json, validate_checklist


def build_voice_checklist(chat):
    voice = deepcopy(chat)
    voice.update({
        "name": "Freedom Broker — адаптация чек-листа для звонков",
        "version": "voice-adapted-1",
        "status": "official",
        "source": "Базовый CQA_Chat_Quality_Checklist 1.pdf, страницы 1–3; разрешение и уточнение организаторов для устной речи передано пользователем в переписке. Формулировки голосовой адаптации подготовлены командой, отдельным официальным PDF не являются.",
        "adaptation_status": "team_adaptation_based_on_organizer_clarification",
        "applicable_channels": ["voice call"],
        "assessment_scope": {
            "default_basis": "transcript_only",
            "audio_optional_dimensions": ["темп речи", "дикция", "разборчивость произношения"],
            "notes": "При оценке по транскрипту не делать выводов о дикции, темпе, акустической разборчивости, тоне или перебиваниях. Ошибки ASR не считать речевыми ошибками оператора. Разрывы timestamps не доказывают молчание. Внутренние консультации при удержании клиента не считать автоматически слышимыми клиенту."
        }
    })
    by_id = {c["id"]: c for c in voice["criteria"]}
    by_id["contact"]["description"] = "Проверяйте первое обращение человека-оператора к клиенту: приветствие на языке клиента и представление. Приветствие IVR не засчитывать. Маркер [Имя скрыто] в позиции представления не означает, что оператор не назвал имя. Если начало или имя искажены ASR и факт представления нельзя установить, выберите «не уверен»."
    by_id["needs"]["description"] = "Оцените учёт уже названных сведений и необходимые уточнения перед консультацией. Учитывайте контекст обратного звонка, если он подтверждён в записи, но не придумывайте содержание предыдущего разговора. Сбор данных для идентификации сам по себе не заменяет выяснения запроса."
    by_id["identification"]["description"] = "Проверка личности должна быть подтверждена до раскрытия сведений счёта или защищённого действия. В звонке подтверждением может быть явное «идентификация пройдена» оператора или системы после проверки. Сам запрос ФИО/кода не доказывает успешную проверку. При скрытых данных, обратном звонке или неясной области действия предыдущей проверки не делайте вывод без достаточных оснований."
    by_id["identification"]["fail_rule"] = "Идентификация требовалась перед защищённым действием или раскрытием данных, но своевременная проверка в разговоре не подтверждена. При неполном фрагменте или неясной допустимости проверки в предыдущем звонке выберите «не уверен» и укажите ограничение."
    by_id["consultation"]["description"] += " Для звонка оцените ответы на все вопросы клиента, отсутствие ошибочной информации и объяснение необходимых действий. Конкретная эскалация с объяснённым следующим шагом может закрывать запрос без немедленного решения. Внутреннее обсуждение сотрудников не заменяет доведение ответа до клиента. Правила продуктов и услуг сверяйте с материалами брокера; отсутствие эталонного ответа на данный разговор не разрешает выдумывать его."
    by_id["consultation"]["na_rule"] = "Разговор закончился до того, как клиент сформулировал запрос."
    management = by_id["management"]
    management["name"] = "Ведение разговора, понятность устной речи и управление паузами"
    management["description"] = "Сохранены ступени базового чек-листа: 10 — разговор логичный, объяснения понятны, формулировки уместны и корректны, необходимое ожидание обозначено; 7 — один заметный сбой, но клиент понимает дальнейшие действия; 4 — клиент переспрашивает из-за формулировок или порядка объяснений; 0 — бессвязные или противоречивые объяснения делают ход разговора непонятным. По транскрипту оценивайте только наблюдаемые логику, формулировки и явные предупреждения об ожидании/удержании. Темп, дикцию, акустическую разборчивость и интонацию можно оценивать только после прослушивания аудио. Не снижайте оценку из-за ошибок распознавания или разницы timestamps без доказанного необъяснённого ожидания. Применение этих ступеней к устной речи — адаптация команды по разрешению организаторов."
    management["pass_rule"] = "Выберите одну из ступеней по наблюдаемой логике, понятности, уместности формулировок и управлению ожиданием. Укажите, оценён ли только транскрипт или также прослушано аудио."
    management["fail_rule"] = "Снижение обоснуйте конкретным наблюдаемым сбоем общения с клиентом. Не путайте ASR с речью оператора, внутренний разговор на удержании — с обращением к клиенту, а полноту консультации — с понятностью её подачи. Если сбой нельзя отделить от искажения записи, выберите «не уверен»."
    by_id["empathy"]["description"] += " По транскрипту оценивайте слова и адресную реакцию; тон и интонацию без прослушивания не угадывайте. Если интерпретация зависит от интонации или искажения ASR, отметьте неопределённость."
    by_id["closing"]["description"] = "Нужны (подведение итога ИЛИ предложение дальнейшей помощи) И прощание. Эти части могут находиться в нескольких заключительных репликах. Одно системное событие «клиент завершил разговор» не доказывает внезапный обрыв и автоматически не даёт N/A. Если разговор оборван до возможности завершения, укажите конкретный признак прерывания."
    by_id["closing"]["na_rule"] = "Разговор прерван до возможности оператора завершить его; это подтверждается контекстом, а не только обычным событием завершения звонка."
    by_id["critical_errors"]["description"] += " Для звонков оценивайте то, что сказано клиенту; не считайте внутреннее обсуждение коллег на удержании утечкой без доказательства, что клиент его слышал. Передача данных самому клиенту оценивается с учётом подтверждённой идентификации; при неясной границе проверки отметьте неопределённость."
    return validate_checklist(voice)


if __name__ == "__main__":
    directory = Path(__file__).resolve().parent
    result = build_voice_checklist(read_json(directory / "checklist.official.json"))
    atomic_json(directory / "checklist.voice.json", result)
    print("Built annotation/checklist.voice.json; chat rubric preserved")
